  <input id="predictedMagnitudeInput" type="range" min="0" max="2" step="0.05" value="1"
    oninput="document.getElementById('predictedMagnitudeVal').value=this.value;update_predictedMagnitude(+this.value)">
</label>
<button onclick="trigger_reset()">Reset vectors</button>
