<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var W = 800, H = 560;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);
draw.rect(W, H).fill('#ffffff');

var PPU = 100;                       // pixels per flow unit
var O = { x: 35, y: 520 };           // common origin (lower-left)

var GT0 = { x: 435, y: -475 };       // ground-truth offset from origin
var PR0 = { x: 530, y: -220 };       // predicted offset (base, before scaling)

var gt = { x: GT0.x, y: GT0.y };     // current ground-truth offset
var predBase = { x: PR0.x, y: PR0.y };
var predScale = 1;
var metric = 'Endpoint error';

var gGrid = draw.group();
var gRays = draw.group();
var gArc = draw.group();
var gRed = draw.group();
var gArrows = draw.group();
var gLabels = draw.group();
var gHandles = draw.group();
var gRead = draw.group();

/* ---------- static faint grid + axes through the origin ---------- */
(function () {
  for (var x = 0; x <= W; x += 50) gGrid.line(x, 0, x, H).stroke({ color: '#eef1f4', width: 1 });
  for (var y = 0; y <= H; y += 50) gGrid.line(0, y, W, y).stroke({ color: '#eef1f4', width: 1 });
  gGrid.line(0, O.y, W, O.y).stroke({ color: '#dde2e7', width: 1.6 });
  gGrid.line(O.x, 0, O.x, H).stroke({ color: '#dde2e7', width: 1.6 });
})();

/* ---------- helpers ---------- */
function tipGT() { return { x: O.x + gt.x, y: O.y + gt.y }; }
function tipPR() { return { x: O.x + predBase.x * predScale, y: O.y + predBase.y * predScale }; }
function units(p) { return { u: (p.x - O.x) / PPU, v: (O.y - p.y) / PPU }; }
function fmt(n) { return (Math.round(n * 100) / 100).toFixed(2); }

function drawArrow(g, o, t, color, sw, hl, hw) {
  var dx = t.x - o.x, dy = t.y - o.y, L = Math.hypot(dx, dy);
  if (L < 3) return null;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  hl = Math.min(hl, L * 0.85);
  var b = { x: t.x - ux * hl, y: t.y - uy * hl };
  var notch = { x: t.x - ux * hl * 0.70, y: t.y - uy * hl * 0.70 };
  g.line(o.x, o.y, b.x + ux * hl * 0.45, b.y + uy * hl * 0.45)
    .stroke({ color: color, width: sw, linecap: 'round' });
  g.polygon([[t.x, t.y], [b.x + px * hw, b.y + py * hw], [notch.x, notch.y], [b.x - px * hw, b.y - py * hw]])
    .fill(color);
  return g;
}

function halo(t) {
  return t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function polar(cx, cy, r, a) { return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) }; }

/* ---------- main render ---------- */
function render() {
  gRays.clear(); gArc.clear(); gRed.clear(); gArrows.clear();
  gLabels.clear(); gHandles.clear(); gRead.clear();

  var T = tipGT(), P = tipPR();
  var showEPE = (metric === 'Endpoint error' || metric === 'Both');
  var showANG = (metric === 'Angular error' || metric === 'Both');

  var aG = Math.atan2(T.y - O.y, T.x - O.x);
  var aP = Math.atan2(P.y - O.y, P.x - O.x);
  var Lp = Math.hypot(P.x - O.x, P.y - O.y);
  var Lg = Math.hypot(T.x - O.x, T.y - O.y);
  var d = aG - aP;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  var thetaDeg = Math.abs(d) * 180 / Math.PI;

  /* dashed unit-direction rays (angular mode) */
