})();

/* ---------- helpers ---------- */
function tipGT() { return { x: O.x + gt.x, y: O.y + gt.y }; }
function tipPR() { return { x: O.x + predBase.x * predScale, y: O.y + predBase.y * predScale }; }
function units(p) { return { u: (p.x - O.x) / PPU, v: (O.y - p.y) / PPU }; }
function fmt(n) { return (Math.round(n * 100) / 100).toFixed(2); }

function drawArrow(g, o, t, color, sw, hl, hw) {
  var dx = t.x - o.x, dy = t.y - o.y, L = Math.hypot(dx, dy);
  if (L < 3) return null;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  hl = Math.min(hl, L * 0.85);
  var b = { x: t.x - ux * hl, y: t.y - uy * hl };
  var notch = { x: t.x - ux * hl * 0.70, y: t.y - uy * hl * 0.70 };
  g.line(o.x, o.y, b.x + ux * hl * 0.45, b.y + uy * hl * 0.45)
    .stroke({ color: color, width: sw, linecap: 'round' });
  g.polygon([[t.x, t.y], [b.x + px * hw, b.y + py * hw], [notch.x, notch.y], [b.x - px * hw, b.y - py * hw]])
    .fill(color);
  return g;
}

function halo(t) {
  return t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
}

function polar(cx, cy, r, a) { return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) }; }

/* ---------- main render ---------- */
function render() {
  gRays.clear(); gArc.clear(); gRed.clear(); gArrows.clear();
  gLabels.clear(); gHandles.clear(); gRead.clear();

  var T = tipGT(), P = tipPR();
  var showEPE = (metric === 'Endpoint error' || metric === 'Both');
  var showANG = (metric === 'Angular error' || metric === 'Both');

  var aG = Math.atan2(T.y - O.y, T.x - O.x);
  var aP = Math.atan2(P.y - O.y, P.x - O.x);
  var Lp = Math.hypot(P.x - O.x, P.y - O.y);
  var Lg = Math.hypot(T.x - O.x, T.y - O.y);
  var d = aG - aP;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  var thetaDeg = Math.abs(d) * 180 / Math.PI;

  /* dashed unit-direction rays (angular mode) */
  if (showANG) {
    var rg = Math.min(Lg + 55, 560), rp = Math.min(Lp + 55, 560);
    var eg = polar(O.x, O.y, rg, aG), ep = polar(O.x, O.y, rp, aP);
    gRays.line(O.x, O.y, eg.x, eg.y).stroke({ color: '#8d99a6', width: 2, dasharray: '7,6' });
    if (Lp > 6) gRays.line(O.x, O.y, ep.x, ep.y).stroke({ color: '#8d99a6', width: 2, dasharray: '7,6' });
  }

  /* angular arc */
  if (Lp > 6) {
    var R = 150;
    var s = polar(O.x, O.y, R, aP), e = polar(O.x, O.y, R, aG);
    var sweep = d > 0 ? 1 : 0;
    var large = Math.abs(d) > Math.PI ? 1 : 0;
    var arc = gArc.path('M ' + s.x + ' ' + s.y + ' A ' + R + ' ' + R + ' 0 ' + large + ' ' + sweep + ' ' + e.x + ' ' + e.y)
      .fill('none')
      .stroke({ color: showANG ? '#1a7f37' : '#cfd6dc', width: showANG ? 3.5 : 2 });
    var mid = polar(O.x, O.y, R + 30, aP + d / 2);
    var th = gArc.text('θ = ' + thetaDeg.toFixed(1) + '°')
      .font({ family: 'Times New Roman, serif', size: 26, anchor: 'middle', style: 'italic' })
      .fill(showANG ? '#1a7f37' : '#c3cad1')
      .center(mid.x, mid.y);
    halo(th);
    if (showANG) {
      arc.css('cursor', 'pointer')
        .on('mousemove', function (ev) { showTooltip('Angular error θ = ' + thetaDeg.toFixed(1) + '° — the opening angle at the origin', ev); })
        .on('mouseleave', hideTooltip)
        .on('click', function () {
          showPopup('Angular error', 'Angular error measures only the angle between the predicted and the ground-truth flow direction. It ignores how long each vector is, so a prediction that points perfectly but moves twice too far scores zero angular error.');
        });
    }
  }

  /* red endpoint-error segment */
  var seg = gRed.line(T.x, T.y, P.x, P.y)
    .stroke({
      color: showEPE ? '#ff0000' : '#a9b2ba',
      width: showEPE ? 7 : 3.5,
      linecap: 'butt',
      dasharray: showEPE ? '' : '8,7'
    });
  var epe = Math.hypot((T.x - P.x) / PPU, (T.y - P.y) / PPU);
  seg.css('cursor', 'pointer')
    .on('mousemove', function (ev) { showTooltip('Endpoint error = ' + fmt(epe) + ' (distance between the two tips)', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Endpoint error', 'The red segment is the vector difference (u,v) − (û,v̂) drawn in place. Its length is the endpoint error, so any mistake in direction OR in magnitude lengthens it. Only a prediction whose tip lands exactly on the ground-truth tip gives zero.');
    });

  /* arrows */
  var gGtArrow = gArrows.group();
  drawArrow(gGtArrow, O, T, '#000000', 10, 56, 25);
  gGtArrow.css('cursor', 'pointer')
    .on('mousemove', function (ev) { var q = units(T); showTooltip('Ground-truth flow (u, v) = (' + fmt(q.u) + ', ' + fmt(q.v) + ')', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Ground-truth flow (u, v)', 'This is the true motion of the pixel between two frames. Every error metric is measured relative to this reference vector — change it and the same prediction can become good or bad.'); });

  var gPrArrow = gArrows.group();
  drawArrow(gPrArrow, O, P, '#000000', 10, 50, 23);
  gPrArrow.css('cursor', 'pointer')
    .on('mousemove', function (ev) { var q = units(P); showTooltip('Predicted flow (û, v̂) = (' + fmt(q.u) + ', ' + fmt(q.v) + ')', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Predicted flow (û, v̂)', 'This is what the optical-flow algorithm estimated for the same pixel. Drag its tip, or scale it along its own direction with the slider, and watch how the two metrics react differently.'); });

  /* math labels */
  halo(gLabels.text('(u, v)')
    .font({ family: 'Times New Roman, serif', size: 42, anchor: 'end', style: 'italic' })
    .fill('#000').attr({ x: 400, y: 62 })).attr({ x: 400, y: 62 });

  halo(gLabels.text('(û, v̂)')
    .font({ family: 'Times New Roman, serif', size: 42, anchor: 'middle', style: 'italic' })
    .fill('#000').attr({ x: 520, y: 392 })).attr({ x: 520, y: 392 });

  var errCol = showEPE ? '#000000' : '#b3bbc2';
  halo(gLabels.text('Endpoint').font({ family: 'Times New Roman, serif', size: 36, anchor: 'start' })
    .fill(errCol).attr({ x: 590, y: 88 })).attr({ x: 590, y: 88 });
  halo(gLabels.text('error').font({ family: 'Times New Roman, serif', size: 36, anchor: 'start' })
    .fill(errCol).attr({ x: 590, y: 140 })).attr({ x: 590, y: 140 });

  /* drag handles */
  makeHandle(T, 'gt');
  if (Lp > 8) makeHandle(P, 'pred');

  /* readout panel */
  var qg = units(T), qp = units(P);
  gRead.rect(196, 96).move(14, 14).radius(6).fill('#ffffff').opacity(0.93).stroke({ color: '#ccd3da', width: 1 });
  var lines = [
    '(u, v)  = (' + fmt(qg.u) + ', ' + fmt(qg.v) + ')',
    '(û, v̂) = (' + fmt(qp.u) + ', ' + fmt(qp.v) + ')',
    'EPE = ' + fmt(epe),
    'θ = ' + thetaDeg.toFixed(1) + '°'
  ];
  var cols = ['#111', '#111', showEPE ? '#cc0000' : '#9aa3ab', showANG ? '#1a7f37' : '#9aa3ab'];
  for (var i = 0; i < lines.length; i++) {
    gRead.text(lines[i]).font({ family: 'Georgia, serif', size: 16, anchor: 'start' })
      .fill(cols[i]).attr({ x: 26, y: 26 + i * 22 });
  }
}

function makeHandle(p, which) {
  var c = gHandles.circle(22).center(p.x, p.y)
    .fill({ color: '#ffffff', opacity: 0.38 })
    .stroke({ color: '#2b7fd4', width: 2.6 })
    .css('cursor', 'grab');
  c.on('mouseenter', function () { c.fill({ color: '#cfe8ff', opacity: 0.85 }); });
  c.on('mouseleave', function () { c.fill({ color: '#ffffff', opacity: 0.38 }); hideTooltip(); });
  c.on('mousemove', function (ev) {
    showTooltip(which === 'gt' ? 'Drag: move the ground-truth tip' : 'Drag: move the predicted tip', ev);
  });
  c.on('pointerdown', function (ev) { startDrag(which, ev); });
}

/* ---------- dragging ---------- */
var dragging = null;
function toLocal(ev) {
  var pt = draw.node.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  var m = draw.node.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  var q = pt.matrixTransform(m.inverse());
  return { x: q.x, y: q.y };
}
function startDrag(which, ev) {
  ev.preventDefault();
  dragging = which;
  hideTooltip();
}
window.addEventListener('pointermove', function (ev) {
  if (!dragging) return;
  var p = toLocal(ev);
  p.x = Math.max(22, Math.min(W - 24, p.x));
  p.y = Math.max(22, Math.min(H - 22, p.y));
  if (dragging === 'gt') {
    gt.x = p.x - O.x; gt.y = p.y - O.y;
  } else {
    if (predScale < 0.12) { predScale = 1; syncSlider(1); }
    predBase.x = (p.x - O.x) / predScale;
    predBase.y = (p.y - O.y) / predScale;
  }
  render();
});
window.addEventListener('pointerup', function () { dragging = null; });

/* ---------- controls ---------- */
function toggle_metricView(v) { metric = v; render(); }

function update_predictedMagnitude(v) { predScale = v; render(); }

function syncSlider(v) {
  var s = document.getElementById('predictedMagnitudeInput');
  var o = document.getElementById('predictedMagnitudeVal');
  if (s) s.value = v;
  if (o) o.value = v;
}

function trigger_reset() {
  gt = { x: GT0.x, y: GT0.y };
  predBase = { x: PR0.x, y: PR0.y };
  predScale = 1; syncSlider(1);
  metric = 'Endpoint error';
  document.getElementById('metricViewInput').value = 'Endpoint error';
  render();
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'Two flow vectors, one origin',
    narration: 'The long black arrow is the ground-truth flow (u, v) and the shorter one is the predicted flow (û, v̂); both start at the same pixel. The red segment between their tips is the endpoint error.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1 }
  },
  {
    title: 'Drag the prediction',
    narration: 'Drag the tip of (û, v̂) anywhere: the red segment stretches and shrinks in real time. Bring the tip onto the ground-truth tip and the error collapses to zero.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1 }
  },
  {
    title: 'Right direction, wrong length',
    narration: 'Scale the prediction along its own direction. The vectors still point the same way, yet the red segment keeps growing — magnitude errors count fully.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1.8 }
  },
  {
    title: 'Angular error tells a different story',
    narration: 'Switch to angular error: the arc at the origin stays the same size while you scale the vector, so this metric is blind to the magnitude mistake that endpoint error just punished.',
    state: { metricView: 'Angular error', predictedMagnitude: 1.8 }
  },
  {
    title: 'Compare the two metrics',
    narration: 'With both overlays on, move the tips around and watch EPE and θ change independently — a small angle can hide a large endpoint error, and a short vector can have a huge angle but a tiny EPE.',
    state: { metricView: 'Both', predictedMagnitude: 1 }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('metricViewInput').value = s.state.metricView;
  toggle_metricView(s.state.metricView);
  syncSlider(s.state.predictedMagnitude);
  update_predictedMagnitude(s.state.predictedMagnitude);
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
render();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Endpoint error is the Euclidean distance between the tip of the predicted flow vector and the tip of the ground-truth flow vector, so it penalizes both direction and magnitude mistakes at once.
KEY INSIGHT (what students should walk away understanding): Endpoint error is just the length of the vector difference (u,v) − (û,v̂): one number that simultaneously charges for pointing the wrong way and for moving the wrong amount.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
