draw.rect(W, H).fill('#ffffff');

var PPU = 100;                        // px per flow unit
var O = { x: 32, y: 645 };            // common origin (lower-left)

var GT0 = { x: 546, y: -629 };        // ground-truth offset from origin
var PR0 = { x: 632, y: -343 };        // predicted offset (base, before scaling)

var gt = { x: GT0.x, y: GT0.y };
var predBase = { x: PR0.x, y: PR0.y };
var predScale = 1;
var metric = 'Endpoint error';
var showGrid = false;
var canvasHover = false;
var stepIdx = 0;

var SERIF = 'Times New Roman, Times, serif';

var gGrid = draw.group();
var gRays = draw.group();
var gArc = draw.group();
var gRed = draw.group();
var gArrows = draw.group();
var gLabels = draw.group();
var gHandles = draw.group();

/* ---------- optional faint grid (off by default: source is plain white) ---------- */
function renderGrid() {
  gGrid.clear();
  if (!showGrid) return;
  for (var x = 0; x <= W; x += 60) gGrid.line(x, 0, x, H).stroke({ color: '#f3f5f7', width: 1 });
  for (var y = 0; y <= H; y += 60) gGrid.line(0, y, W, y).stroke({ color: '#f3f5f7', width: 1 });
  gGrid.line(0, O.y, W, O.y).stroke({ color: '#e8ecef', width: 1.4 });
  gGrid.line(O.x, 0, O.x, H).stroke({ color: '#e8ecef', width: 1.4 });
}

/* ---------- helpers ---------- */
function tipGT() { return { x: O.x + gt.x, y: O.y + gt.y }; }
function tipPR() { return { x: O.x + predBase.x * predScale, y: O.y + predBase.y * predScale }; }
function units(p) { return { u: (p.x - O.x) / PPU, v: (O.y - p.y) / PPU }; }
function fmt(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function polar(cx, cy, r, a) { return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) }; }
function halo(t, w) {
  return t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': (w == null ? 5 : w), 'stroke-linejoin': 'round' });
}

function drawArrow(g, o, t, color, sw, hl, hw) {
  var dx = t.x - o.x, dy = t.y - o.y, L = Math.hypot(dx, dy);
  if (L < 4) return null;
  var ux = dx / L, uy = dy / L, px = -uy, py = ux;
  hl = Math.min(hl, L * 0.85);
  var b = { x: t.x - ux * hl, y: t.y - uy * hl };
  var notch = { x: t.x - ux * hl * 0.70, y: t.y - uy * hl * 0.70 };
  g.line(o.x, o.y, b.x + ux * hl * 0.5, b.y + uy * hl * 0.5)
    .stroke({ color: color, width: sw, linecap: 'round' });
  g.polygon([[t.x, t.y], [b.x + px * hw, b.y + py * hw], [notch.x, notch.y], [b.x - px * hw, b.y - py * hw]])
    .fill(color);
  return g;
}

/* ---------- serif math labels with explicit caret (hat) glyphs ---------- */
function drawCaret(g, cx, baseY, size, color) {
  var w = 0.30 * size, h = 0.17 * size;
  var bot = baseY - 0.60 * size;          // caret legs sit just above the x-height
  var apex = bot - h;
  var d = 'M ' + (cx - w / 2) + ' ' + bot + ' L ' + cx + ' ' + apex + ' L ' + (cx + w / 2) + ' ' + bot;
  g.path(d).fill('none').stroke({ color: '#ffffff', width: 0.13 * size, linecap: 'round', linejoin: 'round' });
  g.path(d).fill('none').stroke({ color: color, width: 0.062 * size, linecap: 'round', linejoin: 'round' });
}

/* tokens: glyph, advance (fraction of size), wears a hat */
function vecLabel(g, ax, baseY, size, hat, color, anchor) {
  var toks = [['(', 0.39, false], ['u', 0.54, hat], [',', 0.30, false],
              [' ', 0.18, false], ['v', 0.50, hat], [')', 0.39, false]];
  var total = 0, i;
  for (i = 0; i < toks.length; i++) total += toks[i][1] * size;
  var x = (anchor === 'end') ? ax - total : (anchor === 'middle') ? ax - total / 2 : ax;
  var x0 = x;
  for (i = 0; i < toks.length; i++) {
    var c = toks[i][0], adv = toks[i][1] * size;
    if (c !== ' ') {
      var t = g.plain(c).font({ family: SERIF, size: size, style: 'italic' }).fill(color)
        .attr({ x: x, y: baseY });
      halo(t, 5);
      if (toks[i][2]) drawCaret(g, x + adv * 0.46 + size * 0.10, baseY, size, color);
    }
    x += adv;
  }
  return { x0: x0, x1: x0 + total, width: total, baseY: baseY };
}

/* ---------- main render ---------- */
function render() {
  gRays.clear(); gArc.clear(); gRed.clear(); gArrows.clear();
  gLabels.clear(); gHandles.clear();

  var T = tipGT(), P = tipPR();
  var showEPE = (metric === 'Endpoint error' || metric === 'Both');
  var showANG = (metric === 'Angular error' || metric === 'Both');

  var aG = Math.atan2(T.y - O.y, T.x - O.x);
  var aP = Math.atan2(P.y - O.y, P.x - O.x);
  var Lp = Math.hypot(P.x - O.x, P.y - O.y);
  var Lg = Math.hypot(T.x - O.x, T.y - O.y);
  var d = aG - aP;
  while (d > Math.PI) d -= 2 * Math.PI;
  while (d < -Math.PI) d += 2 * Math.PI;
  var thetaDeg = Math.abs(d) * 180 / Math.PI;
  var epe = Math.hypot((T.x - P.x) / PPU, (T.y - P.y) / PPU);

  /* dashed unit-direction rays (angular modes only) */
  if (showANG) {
    var rg = Math.min(Lg + 60, 880), rp = Math.min(Lp + 60, 880);
    var eg = polar(O.x, O.y, rg, aG), ep = polar(O.x, O.y, rp, aP);
    gRays.line(O.x, O.y, eg.x, eg.y).stroke({ color: '#9aa5b1', width: 2, dasharray: '8,7' });
    if (Lp > 8) gRays.line(O.x, O.y, ep.x, ep.y).stroke({ color: '#9aa5b1', width: 2, dasharray: '8,7' });
  }

  /* angular arc — only when the angular metric is selected */
  if (showANG && Lp > 8) {
    var R = Math.min(200, Math.max(120, Math.min(Lg, Lp) * 0.45));
    var s = polar(O.x, O.y, R, aP), e = polar(O.x, O.y, R, aG);
    var sweep = d > 0 ? 1 : 0;
    var large = Math.abs(d) > Math.PI ? 1 : 0;
    var arc = gArc.path('M ' + s.x + ' ' + s.y + ' A ' + R + ' ' + R + ' 0 ' + large + ' ' + sweep + ' ' + e.x + ' ' + e.y)
      .fill('none').stroke({ color: '#1a7f37', width: 3.5 });

    var half = Math.max(0.06, Math.abs(d) / 2);
    var need = 70 / Math.sin(half);
    var rLab = Math.min(Math.max(R + 70, need), Math.min(Lg, Lp) * 0.92 + 120, 700);
    var mid = polar(O.x, O.y, rLab, aP + d / 2);
    mid.x = Math.max(90, Math.min(W - 90, mid.x));
    mid.y = Math.max(46, Math.min(H - 30, mid.y));
    halo(gArc.text('\u03B8 = ' + thetaDeg.toFixed(1) + '\u00B0')
      .font({ family: SERIF, size: 32, anchor: 'middle', style: 'italic' })
      .fill('#1a7f37')).center(mid.x, mid.y);

    arc.css('cursor', 'pointer')
      .on('mousemove', function (ev) { showTooltip('Angular error \u03B8 = ' + thetaDeg.toFixed(1) + '\u00B0 — the opening angle at the origin', ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Angular error', 'Angular error measures only the angle between the predicted and the ground-truth flow direction. It ignores how long each vector is, so a prediction that points perfectly but moves twice too far scores zero angular error.');
      });
  }

  /* red endpoint-error segment — shaft-weight stroke, as in the source */
  var seg = gRed.line(T.x, T.y, P.x, P.y)
    .stroke({
      color: showEPE ? '#ff0000' : '#b3bbc2',
      width: showEPE ? 6 : 4,
      linecap: 'butt',
      dasharray: showEPE ? '' : '9,8'
    });
  var segHit = gRed.line(T.x, T.y, P.x, P.y).stroke({ color: '#fff', width: 24, opacity: 0 });
  segHit.css('cursor', 'pointer')
    .on('mousemove', function (ev) { showTooltip('Endpoint error = ' + fmt(epe) + ' (distance between the two tips)', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Endpoint error', 'The red segment is the vector difference (u,v) \u2212 (\u00FB,\u1E7D) drawn in place. Its length is the endpoint error, so any mistake in direction OR in magnitude lengthens it. Only a prediction whose tip lands exactly on the ground-truth tip gives zero.');
    });

  /* arrows */
  var gGtArrow = gArrows.group();
  drawArrow(gGtArrow, O, T, '#000000', 14, 92, 33);
  gGtArrow.css('cursor', 'pointer')
    .on('mousemove', function (ev) { var q = units(T); showTooltip('Ground-truth flow (u, v) = (' + fmt(q.u) + ', ' + fmt(q.v) + ')', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Ground-truth flow (u, v)', 'This is the true motion of the pixel between two frames. Every error metric is measured relative to this reference vector — change it and the same prediction can become good or bad.'); });

  var gPrArrow = gArrows.group();
  drawArrow(gPrArrow, O, P, '#000000', 14, 86, 32);
  gPrArrow.css('cursor', 'pointer')
    .on('mousemove', function (ev) { var q = units(P); showTooltip('Predicted flow (\u00FB, \u1E7D) = (' + fmt(q.u) + ', ' + fmt(q.v) + ')', ev); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Predicted flow (\u00FB, \u1E7D)', 'This is what the optical-flow algorithm estimated for the same pixel. Drag its tip, or scale it along its own direction with the slider, and watch how the two metrics react differently.'); });

  /* ---- math labels (serif, hats drawn as carets) ---- */
  var MS = 68;
  var gtAX = Math.max(260, Math.min(W - 20, T.x - 95));
  var gtAY = Math.max(MS * 0.9, Math.min(H - 20, T.y + 58));
  vecLabel(gLabels, gtAX, gtAY, MS, false, '#000000', 'end');

  if (Lp > 10) {
    var prAX = Math.max(90, Math.min(W - 90, P.x - 55));
    var prAY = Math.max(MS, Math.min(H - 14, P.y + 145));
    vecLabel(gLabels, prAX, prAY, MS, true, '#000000', 'middle');
  }

  /* 'Endpoint / error' label, just right of the red segment */
  var midX = (T.x + P.x) / 2, midY = (T.y + P.y) / 2;
  var labX = Math.max(40, Math.min(W - 300, midX + 30));
  var labY = Math.max(120, Math.min(H - 70, midY));
  var errCol = showEPE ? '#000000' : '#b3bbc2';
  var gErr = gLabels.group();
  /* leader shown only on hover over the label */
  var leader = gErr.line(midX + 6, midY, labX - 12, labY - 10)
    .stroke({ color: '#f0a0a0', width: 1.4 }).opacity(0);
  halo(gErr.plain('Endpoint').font({ family: SERIF, size: 68 }).fill(errCol)
    .attr({ x: labX, y: labY - 46 }));
  halo(gErr.plain('error').font({ family: SERIF, size: 68 }).fill(errCol)
    .attr({ x: labX, y: labY + 50 }));
  gErr.css('cursor', 'pointer')
    .on('mouseenter', function () { leader.animate(120).opacity(1); })
    .on('mousemove', function (ev) { showTooltip('Endpoint error = ' + fmt(epe) + ' flow units', ev); })
    .on('mouseleave', function () { leader.animate(120).opacity(0); hideTooltip(); })
    .on('click', function () {
      showPopup('Endpoint error', 'EPE = \u2016(u,v) \u2212 (\u00FB,\u1E7D)\u2016. One number charges simultaneously for pointing the wrong way and for moving the wrong amount, which is why it is the standard optical-flow benchmark metric.');
    });

  /* drag handles (hidden until the pointer is over the figure) */
  makeHandle(T, 'gt');
  if (Lp > 10) makeHandle(P, 'pred');
  updateHandleVis();

  /* numeric readout lives in the side panel, not on the drawing */
  var qg = units(T), qp = units(P);
  setText('roGT', '(' + fmt(qg.u) + ', ' + fmt(qg.v) + ')');
  setText('roPR', '(' + fmt(qp.u) + ', ' + fmt(qp.v) + ')');
  setText('roEPE', fmt(epe));
  setText('roTheta', thetaDeg.toFixed(1) + '\u00B0');
}

function setText(id, s) { var el = document.getElementById(id); if (el) el.textContent = s; }

function makeHandle(p, which) {
  var c = gHandles.circle(22).center(p.x, p.y)
    .fill({ color: '#ffffff', opacity: 0.25 })
    .stroke({ color: '#2b7fd4', width: 2.4 })
    .css('cursor', 'grab');
  c.on('mouseenter', function () { c.fill({ color: '#cfe8ff', opacity: 0.95 }); gHandles.opacity(1); });
  c.on('mouseleave', function () { c.fill({ color: '#ffffff', opacity: 0.25 }); hideTooltip(); });
  c.on('mousemove', function (ev) {
    showTooltip(which === 'gt' ? 'Drag: move the ground-truth tip' : 'Drag: move the predicted tip', ev);
  });
  c.on('pointerdown', function (ev) { startDrag(which, ev); });
}

function updateHandleVis() {
  gHandles.opacity((canvasHover || dragging || stepIdx >= 1) ? 1 : 0);
}

/* ---------- dragging ---------- */
var dragging = null;
function toLocal(ev) {
  var pt = draw.node.createSVGPoint();
  pt.x = ev.clientX; pt.y = ev.clientY;
  var m = draw.node.getScreenCTM();
  if (!m) return { x: 0, y: 0 };
  var q = pt.matrixTransform(m.inverse());
  return { x: q.x, y: q.y };
}
function startDrag(which, ev) { ev.preventDefault(); dragging = which; hideTooltip(); }
window.addEventListener('pointermove', function (ev) {
  if (!dragging) return;
  var p = toLocal(ev);
  p.x = Math.max(18, Math.min(W - 18, p.x));
  p.y = Math.max(18, Math.min(H - 18, p.y));
  if (dragging === 'gt') { gt.x = p.x - O.x; gt.y = p.y - O.y; }
  else {
    if (predScale < 0.12) { predScale = 1; syncSlider(1); }
    predBase.x = (p.x - O.x) / predScale;
    predBase.y = (p.y - O.y) / predScale;
  }
  render();
});
window.addEventListener('pointerup', function () { dragging = null; updateHandleVis(); });

var containerEl = document.getElementById('container');
containerEl.addEventListener('mouseenter', function () { canvasHover = true; updateHandleVis(); });
containerEl.addEventListener('mouseleave', function () { canvasHover = false; updateHandleVis(); });

/* ---------- controls ---------- */
function toggle_metricView(v) { metric = v; render(); }
function update_predictedMagnitude(v) { predScale = v; render(); }
function toggle_showGrid(on) { showGrid = on; renderGrid(); }

function syncSlider(v) {
  var s = document.getElementById('predictedMagnitudeInput');
  var o = document.getElementById('predictedMagnitudeVal');
  if (s) s.value = v;
  if (o) o.value = v;
}

function trigger_reset() {
  gt = { x: GT0.x, y: GT0.y };
  predBase = { x: PR0.x, y: PR0.y };
  predScale = 1; syncSlider(1);
  metric = 'Endpoint error';
  document.getElementById('metricViewInput').value = 'Endpoint error';
  render();
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'Two flow vectors, one origin',
    narration: 'The long black arrow is the ground-truth flow (u, v) and the shorter one is the predicted flow (\u00FB, \u1E7D); both start at the same pixel. The red segment between their tips is the endpoint error.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1 }
  },
  {
    title: 'Drag the prediction',
    narration: 'Small blue handles now sit at both tips. Drag the tip of (\u00FB, \u1E7D) anywhere: the red segment stretches and shrinks in real time. Bring the tip onto the ground-truth tip and the error collapses to zero.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1 }
  },
  {
    title: 'Right direction, wrong length',
    narration: 'Scale the prediction along its own direction. The vectors still point the same way, yet the red segment keeps growing — magnitude errors count fully.',
    state: { metricView: 'Endpoint error', predictedMagnitude: 1.8 }
  },
  {
    title: 'Angular error tells a different story',
    narration: 'Switch to angular error: the arc at the origin stays the same size while you scale the vector, so this metric is blind to the magnitude mistake that endpoint error just punished.',
    state: { metricView: 'Angular error', predictedMagnitude: 1.8 }
  },
  {
    title: 'Compare the two metrics',
    narration: 'With both overlays on, move the tips around and watch EPE and \u03B8 change independently — a small angle can hide a large endpoint error, and a short vector can have a huge angle but a tiny EPE.',
    state: { metricView: 'Both', predictedMagnitude: 1 }
  }
];

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('metricViewInput').value = s.state.metricView;
  metric = s.state.metricView;
  syncSlider(s.state.predictedMagnitude);
  predScale = s.state.predictedMagnitude;
  render();
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
renderGrid();
render();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.
